import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山天大畜","description":"周易折中 - 山天大畜","frontmatter":{"title":"山天大畜","description":"周易折中 - 山天大畜"},"headers":[],"relativePath":"zh/classics/zhezhong/032.md","filePath":"zh/classics/zhezhong/032.md"}'),h={name:"zh/classics/zhezhong/032.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山天大畜" tabindex="-1">山天大畜 <a class="header-anchor" href="#山天大畜" aria-label="Permalink to “山天大畜”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>大畜序卦：有无妄然后可畜，故受之以大畜。无妄则为有实，故可畜聚。大畜所以次无妄也。为卦，艮上乾下，天而在于山中，所畜至大之象。畜为畜止，又为畜聚，止则聚矣。取天在山中之象，则为蕴畜；取艮之止，乾则为畜止，止而后有积，故止为畜义。</p><p>大畜：利贞，不家食，吉，利涉大川。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>大阳也以艮畜乾，又畜之大者也。又以内乾刚健，外艮笃实辉光，是以能日新其德而为畜之大也。以卦变言，此卦自需而来，九自五而上。以卦体言，六五尊而尚之。以卦德言，又能止健，皆非大正不能，故其占为“利贞不家食吉”也。又六五下应于乾，为应乎天，故其占又为“利涉大川”也。不家食，谓食禄于朝，不食于家也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>莫大于天，而在山中，艮在上而止乾于下，皆蕴畜至大之象也。在人为学术道德充积于内，乃所畜之大也。凡所畜聚，皆是专言其大者。人之蕴畜，宜得正道，故云“利贞”。若夫异端偏学，所聚至多而不正者，固有矣。既道德充积于内，宜在上位以享天禄，施为于天下，则不独于一身之吉，天下之吉也。若穷处而自食于家，道之否也，故“不家食吉”。所畜既大，宜施之于时，济天下之艰险，乃大畜之用也，故“利涉大川”。此只据大畜之义而言，《彖》更以卦之才德而言。诸爻则惟有止畜之义，盖《易》体道随宜取明且近者。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云 ：某作《本义》，欲将文王卦辞只大纲依文王本义略说，至其所以然之故，却于孔子《彖传》中发之。且如“大畜，利贞，不家食，吉，利涉大川”，只是占得大畜者为“利贞不家食而吉”，利于涉大川。至于“刚上尚贤”等处，乃孔子发明，各有所主。爻象亦然。如此，则不失文王本意，又可见孔子之意。但今未暇整顿耳。</p></li><li><p>胡氏炳文曰 ：“不家食”是贤者不畜于家而畜于朝，“涉大川”又似有畜极而通之意。要之，两“利”字，一“吉”字，占辞自分为三，不必泥而一之也。</p></li></ul><p>象曰：天在山中，大畜；君子以多识前言往行，以畜其德</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>天在山中，不必实有是事，但以其象言之耳。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>天为至大，而在山之中，所畜至大之象。君子观象以大其蕴畜，人之蕴畜由学而大，在多闻前古圣贤之言与行，考迹以观其用，察言以求其心，识而得之以畜成其德，乃大畜之义也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏时曰 ：君子多识前言往行，非徒资闻见而已，所以畜德也。畜德则所畜大矣。世之学者夸多斗靡，以资见闻而已，亦乌用学为哉？</p></li><li><p>丘氏富国曰 ：大畜言畜德，小畜言懿文。德畜虽同，而文德则德之小者也。</p></li><li><p>张氏清子曰 ：天在山中，畜其气也。凡山中有雷雨云风之气，皆天也。</p></li></ul><p>彖曰：大畜，刚健笃实，辉光日新其德</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦德释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>以卦之才德而言也。干体刚健，艮体笃实。人之才，刚健笃实，则所畜能大，充实而有辉光。畜之不已，则其德日新也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰：畜有三义：以蕴畜言之，畜德也；以畜养言之，畜贤也；以畜止言之，畜健也。刚健笃实，辉光日新其德，此蕴畜之大者；养贤以及万民，此畜养之大者；干天下之至健而四五能畜之，此畜止之大者。故彖传兼此三者言之。</li></ul><p>刚上而尚贤，能止健，大正也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦变、卦体释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>刚上，阳居上也。阳刚居尊位之上，为尚贤之义；止居健上，为能止健之义。止乎健者，非大正，则安能以刚阳在上与尊尚贤德、能止至健，皆大正之道也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏忠孝曰：大有，有贤之卦也；大畜，畜贤之卦也。故曰“刚上而尚贤”。</p></li><li><p>朱子语类云：能止健，不说健而止，见得是艮来止这干。</p></li></ul><p>不家食吉，养贤也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>亦取尚贤之象。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>梁氏寅曰：养贤者，亦取尚贤之象。自刚上而言，则谓之尚贤，所以尽其礼也；自不家食而言，则谓之养贤，所以重其禄也。</li></ul><p>利涉大川，应乎天也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>亦以卦体而言。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>大畜之人，所宜施其所畜以济天下，故不食于家则吉。谓居天位，享天禄也。国家养贤，贤者得行其道也。利涉大川，谓大有蕴畜之人，宜济天下之艰险也。彖更发明卦才，云所以能涉大川者，以应乎天也。六五君也，下应干之中爻，乃大畜之君，应干而行也。所行能应乎天，无艰险之不可济，况其他乎？</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：卦有干体者多曰“利涉大川”，健故也。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>尚贤、止健之义，六爻中皆可见。然夫子释卦，必以“刚健笃实”一句居首者，盖莫大于天德。刚健者，天德也。人欲畜其天德，非笃实则不能。笃实者，《论语》所谓“重”、《大学》所谓“静”、《中庸》所谓“暗”。虽至于达天德，而必有以固其聪明圣智。故笃实者，学之所以成始成终。如艮为万物之所成终，而所成始也。此义最大，故首发之。</p><p>初九：有厉利已</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>乾之三阳为艮所止，故内外之卦各取其义。初九为六四所止，故其占往则有危而利于止也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>大畜，艮止畜乾也，故乾三爻皆取被止为义，艮三爻皆取止之为义。初以阳刚又健体而居下，必上进者也。六四在上，畜止于已，安能敌在上得位之尊？若犯之而进，则有危厉，故利在已而不进也。在他卦，则四与初为正应相援者也；在大畜，则相应乃为相止畜。上与三皆阳，则为合志，盖阳皆上进之物，故有同志之象而无相止之义。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏清曰 ：初九不可进而未必能自不进，故戒之云进则有厉，惟利于已也。若九二之处中能自止而不进者也，则以其所能言之曰“舆说輹”。</li></ul><p>象曰：有厉，利己不犯灾也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>有危则宜己不可犯灾，危而行也，不度其势而进，有灾必矣。</p><p>九二：舆说輹</p><ul><li>蔡氏清曰 ：初九不可进而未必能自不进，故戒之云进则有厉，惟利于已也。若九二之处中能自止而不进者也，则以其所能言之曰“舆说輹”。</li></ul><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>九二亦为六五所畜，以其处中故能自止而不进，有此象也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>二为六五所畜止，不可进也。五据在上之尊，岂可犯也？二虽刚健之体，然其处得中道，故进止无失。虽志于进，度其尊之不可，则止而不行，如车舆说去轮輹，谓不行也。</p><p>象曰：舆说輹，中无尤也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>舆说輹而不行者，盖其处得中道，动不失宜，故无过尤也。善莫善于刚中柔中者，不至于过柔耳。刚中中而才也。初九处不得中，故戒以有危宜已；二得中，进止自无过差，故但言舆说輹，谓其能不行也。不行则无尤矣。初与二干体刚健而不足以进，四与五阴柔而能止。时之盛衰，势之强弱，学易者所宜深识也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>吕氏祖谦曰 ：二以刚而居中，能度其宜，见其不可，自说其舆輹而不行也，故曰中无尤。</li></ul><p>九三：良马逐，利艰贞，曰闲舆卫，利有攸往</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>三以阳居健极，上以阳居畜极，极而通之时也。又皆阳爻，故不相畜而俱进，有良马逐之象焉。然过刚锐进，故其占必戒以艰贞，闲习乃利于有往也。曰“当为日月之日”。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>三刚健之极，而上九之阳亦上进之物，又处畜之极而思变也，与三乃不相畜而志同相应以进者也。三以刚健之才而在上者，与合志而进，其进如良马之驰逐，言其速也。虽其进之势速，不可恃其才之健与上之应而忘备与慎也，故宜艰难其事而由贞正之道。舆者，用行之物；卫者，所以自防。当自日常闲习其车舆与其防卫，则利有攸往矣。三乾体而居正，能贞者也。当其锐进，故戒以知难与不失其贞也。志既锐于进，虽刚明有时而失，不得不戒也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰 ：初九在初，故称童牛；九二以刚居柔无𫝑，故为豮豕；九三纯乾，故为良马。</li></ul><p>象曰：利有攸往，上合志也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>所以利有攸往者，以与在上者合志也。上九阳性上进，且畜已极，故不下畜三，而与合志上进也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>赵氏汝梅曰 ：他卦阴阳应为得，此则为畜；他卦阴阳敌为不胥，与此则为合。</li></ul><p>六四：童牛之牿，元吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>童者，未角之称；牿，施横木于牛角以防其触。诗所谓楅衡者也。止之于未角之时，为力则易，大善之吉也，故其象占如此。学记曰：“禁于未发之谓豫”，正此意也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>以位而言，则四下应于初，畜初者也。初居最下，阳之微者，微而畜之，则易制，犹童牛而加牿，大善而吉也。概论畜道，则四艮体居上位，而得正是以正德居大臣之位，当畜之任者也。大臣之任，上畜止人君之邪心，下畜止天下之恶。人人之恶止于初，则易；既盛而后禁，则扞格而难胜。故上之恶既甚，则虽圣人救之，不能免违拂；下之恶既甚，则虽圣人治之，不能免刑戮。莫若止之于初，如童牛而加牿，则元吉也。牛之性抵触以角，故牿以制之。若童犊始角而加之以牿，使抵触之性不发，则易而无伤。以况六四能畜止上下之恶于未发之前，则大善之吉也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云 ：大畜下卦取其能自畜而不进，上卦取其能畜彼而不使进。然四能止之于初，故为力易；五则阳已进而止之，则难以柔居尊，得其机会可制，故亦吉，但不能如四之元吉耳。</li></ul><p>象曰：六四元吉，有喜也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>天下之恶已盛而止之，则上劳于禁制，而下伤于刑诛。故畜止于㣲小之前，则大善而吉，不劳而无伤，故可喜也。四之畜初是也，上畜亦然。</p><p>六五：豮豕之牙，吉</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>阳已进而止之，不若初之易矣。然以柔居中而当尊位，是以得其机会而可制，故其象如此。占虽吉而不言元也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>六五居君位，止畜天下之邪恶。夫以亿兆之众，发其邪欲之心，人君欲力以制之，虽密法严刑不能胜也。夫物有总摄，事有机会。圣人操得其要，则视亿兆之心犹一心，道之斯行，止之则戢，故不劳而治。其用若豮豕之牙也。豕刚躁之物，而牙为猛利，若强制其牙，则用力劳而不能止其躁猛。虽絷之维之，不能使之变也。若豮去其𫝑，则牙虽存而刚躁自止。其用如此，所以吉也。君子法豮豕之义，知天下之恶不可以力制也，则察其机，持其要，塞绝其本原，故不假刑法严峻而恶自止也。且如止盗，民有欲心，见利则动。苟不知教而迫于饥寒，虽刑杀日施，其能胜亿兆利欲之心乎？圣人则知所以止之之道，不尚威刑而修政教，使之有农桑之业，知廉耻之道，虽赏之不窃矣。故止恶之道，在知其本，得其要而已。不严刑于彼而修政于此，是犹患豕牙之利，不制其牙而豮其𫝑也。</p><p>象曰：六五之吉，有庆也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>在上者不知止恶之方，严刑以敌民欲，则其伤甚而无功。若知其本，制之有道，则不劳无伤而俗革，天下之福庆也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吕氏大临曰 ：六四六五皆以柔畜刚止健者也。牛之刚健在角，豕之刚健在牙。初九居健之始，其健未著，若童牛然。禁于未发，以牿闲之。及其长也，无所用其健，岂特不暴而已，安于驯柔，可驾而服，故有喜也。九二居健之中，其健已具，若豕之牙渐不可制。六五居尊守中，能以柔道杀其刚暴之气，若豮豕然。其牙虽刚，莫之能暴，可以养畜而无虞，故有庆也。</p></li><li><p>项氏安世曰 ：喜者据己言之，庆则其喜及人。五居君位，故及人也。若论止物之道，则制之于初乃为大善，故四为元吉，五独得吉而已。</p></li><li><p>蔡氏清曰 ：五不如四所处之易者，时不同也；四不如五所济之广者，位不同也。</p></li></ul><p>上九：何天之衢，亨</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>何天之衢，言何其通达之甚也。畜极而通，豁达无碍，故其象占如此。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>予闻之胡先生曰：“天之衢亨，误加‘何’字。”事极则反，理之常也。故畜极而亨，小畜畜之小，故极而成大畜，畜之大故极而散。极既当变，又阳性上行，故遂散也。天衢，天路也，谓空虚之中云气飞鸟往来，故谓之天衢。天衢之亨，谓其亨通旷阔无有蔽阻也。在畜道则变矣，变而亨，非畜道之亨也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张氏浚曰 ：刚在上为何？何谓胜其任？</p></li><li><p>王氏宗传曰 ：《彖传》曰“刚上而尚贤”，则上九是也。以阳德而居五之上，为五所尚，此所以有何天之衢之象。天衢，通显之地也。下之三阳由已上进，故九三曰“良马逐”，又曰“上合志也”。此贤者之道所以亨也。何如？何校之何？释文曰：“梁武帝读音贺是也。”言以身任天下之责，当畜贤之时，为五所尚，主张贤路，贤者之得志莫盛于斯也。</p></li><li><p>呉氏澄曰 ：后汉王延寿《鲁灵光殿赋》云：“荷天衢以元亨。”何作荷，何天之衢其辞，犹诗言“何天之休”，“何天之龙”。大畜者，一阳止于外而三阳藏畜于内，畜极则散，止极则行，故上九虽艮体，至畜之终则不止而行也。</p></li><li><p>胡氏炳文曰 ：随畜随发，不足为大畜。惟畜之极而通豁逹无碍，如天衢然。此不徒为仕者之占，大学章句所谓“用力之久，一旦豁然贯通”者，亦是此意。多识前言往行以畜其德者，以之可也。</p></li><li><p>蔡氏清曰 ：观畜极而通之意，则知君子患屈之未至耳，不患其不伸也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>何字，程传以为误加，本义以为发语，而诸家皆以荷字为解，义亦可从。盖刚上尚贤者，惟上九一爻当之，且为艮主，是卦之主也，故取尚贤之义，则是贤路大通。卦所谓“不家食”者，此已取艮主之义，则能应天止健；卦所谓“涉大川”者，此故天衢者喻其通也。荷天之衢者，言其遇时之通也。《杂卦》云：“大畜时也。”正谓此也。呉氏引商颂之诗者，语意尢近。</p><p>象曰：何天之衢，道大行也</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>何以谓之天衢？以其无止碍，道路大通行也。以天衢非常语，故象特设问曰“何谓天之衢”。以道路大通行取空豁之状也。以象有“何”字，故爻下亦误加之。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>㳺氏酢曰 ：畜道之成，贤路自我而四达矣，故曰“何天之衢”。亨。彖曰“刚上而尚贤”，则大畜之义主于上九也。崇俊良以列庶位，推毂贤路，使天下无家食之贤者，上九之任也。天下至于无家食之贤，则道之大行，孰盛于此？</p></li><li><p>沈氏该曰 ：何天之衢，尚贤也。大畜之时，已独居上五，以柔尚之。畜盛德而处上，止众贤而聚王庭，以天衢之亨为己之任。畜道至此，贤路不塞，其道盛矣，故曰“道大行也”。</p></li><li><p>吕氏祖谦曰 ：畜极则散，如伊尹乐尧舜之道，居畎亩之中，其畜可谓大矣。必佐汤以发其所蕴，是得时如天之衢也。故曰“道行得时”，行道之谓也。</p></li><li><p>何氏楷曰 ：备于身之谓德，达于世之谓道。道可大行，其亨可知。彖所谓“不家食吉，而利渉大川”者，此也。</p></li></ul><p>总论</p><ul><li><p>胡氏炳文曰：他卦取阴阳相应，此取相畜。内卦受畜以自止为义，外卦能畜以止之为义。独三与上居内外卦之极，畜极而通，不取止义。</p></li><li><p>叶氏良佩曰：卦彖兼取畜止、畜聚二义，大象专取畜聚义，六爻专取畜止义。初九进则有厉，惟利于己，知难而止者也；九二处得中道，能说輹而不行，时止而止者也；九三与上合志，其进也如良马之驰逐，此畜极而通之象，然犹以艰贞闲习为戒者，虑其可进而锐于进也；六四当大畜之任，能止恶于初，若童牛始角而加之以牿，则大善之吉也；六五制恶有道，得其机会，故其象为豮豕之牙，其占虽吉，然比之于四则有间矣；或问六四元吉传曰有喜，六五之吉乃曰有庆，何也？曰论为力之难易，则四为易，故曰元吉；论其功之广狭，则五为广，故曰有庆。上九之“亨”，畜极而大通也，故以天之衢为象，“云行雨施，天下平也”，其斯以为道大行乎？案 “有厉”“说輹”，则犹“家食”者也，阻于“大川”者也。“牿牛”“豮豕”，则犹治不肖者也，弘济艰难者也。至“良马逐”则渐通矣。然犹防贤路之崎岖，而“日闲舆卫”，故至于“何天之衢”，然后大道夷而险阻去也，卦爻义之相关者在此。</p></li></ul>',114)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
